const apiBase=import.meta.env.VITE_API_BASE_URL;const api=apiBase?createApiAdapter(apiBase):null;
const theme=createTheme({palette:{mode:'light',primary:{main:'#4c49e8'},secondary:{main:'#b96505'},background:{default:'#f4f6fa',paper:'#fff'},text:{primary:'#17233b',secondary:'#69758a'},success:{main:'#178369'},warning:{main:'#b66a00'},divider:'#e4e8ef'},typography:{fontFamily:'Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif',h4:{fontWeight:720,fontSize:'1.8rem',letterSpacing:'-.7px'},h5:{fontWeight:700},h6:{fontWeight:700,fontSize:'1.05rem'},button:{textTransform:'none',fontWeight:650,fontSize:'.82rem'},body2:{fontSize:'.82rem'}},shape:{borderRadius:6},components:{MuiButton:{defaultProps:{disableElevation:true}},MuiTableCell:{styleOverrides:{root:{padding:'15px 16px',fontSize:'.8rem',borderColor:'#edf0f5'},head:{background:'#fafbfe',color:'#728096',fontWeight:650,fontSize:'.69rem',textTransform:'uppercase',letterSpacing:'.7px',paddingTop:12,paddingBottom:12}}},MuiPaper:{defaultProps:{elevation:0}},MuiTextField:{defaultProps:{size:'small'}},MuiChip:{styleOverrides:{root:{fontSize:'.68rem',fontWeight:650,height:24,borderRadius:4}}}}});
